use strict; use warnings;
my $BIN=$ARGV[0]; my $N=$ARGV[1]||500;
my @alpha = map { chr } (1..255);
my @toks = ('://',':','@','?','#','%','/','//','a','.','-','_','[',']',' ',"\t","\n","\r",'%2F','%41','http','8080','0','65535','65536','..','+','..%2F',':/','%','~','\\','|','"',"'");
srand(1234);
my $bad=0; my $probes=0;
sub run { my $s=shift; open(my $fh,'-|:raw', ($BIN, $s)) or die; local $/; my $o=<$fh>; close $fh; my $ec=$?; return ($o//'', $ec); }
for my $i (1..$N) {
  my $s='';
  my $mode = $i % 3;
  if ($mode==0) { my $L=int(rand(60))+1; $s .= $alpha[int(rand(255))] for 1..$L; }
  elsif ($mode==1) { my $L=int(rand(14))+1; $s .= $toks[int(rand(scalar @toks))] for 1..$L; }
  else { my $L=int(rand(10))+1; $s='http://ex.com'; $s .= '/'.$toks[int(rand(scalar @toks))] for 1..$L; }
  my ($o,$ec)=run($s); $probes++;
  my @problems;
  push @problems, "exit=$ec" if $ec != 0;
  push @problems, "no trailing LF" unless $o =~ /\n\z/;
  my @L = split(/\n/, $o, -1); pop @L; # last empty
  push @problems, "fewer than 5 lines" if @L < 5;
  if (@L>=5) {
    for my $k (0..3) { push @problems, "line".($k+1)." not 0/1: '$L[$k]'" unless $L[$k] eq '0' || $L[$k] eq '1'; }
    push @problems, "line5 not plain decimal: '$L[4]'" unless $L[4] =~ /\A(0|[1-9][0-9]*)\z/;
    my $n = $L[4]+0;
    # reconstruct segments: everything after the 5th LF, split on trailing LFs
    my $idx=0; my $c=0; while ($c<5) { $idx = index($o,"\n",$idx)+1; $c++; }
    my $rest = substr($o,$idx);
    push @problems, "rest doesn't end LF" if length($rest) && $rest !~ /\n\z/;
    my $expect = 8 + length($L[4]) + 1 + (length($rest));
    push @problems, "bytecount mismatch: got ".length($o)." expect $expect" if length($o) != $expect;
    # segments joined by \n : if none contains \n, count must equal n
    my @segs = split(/\n/, $rest, -1); pop @segs;
    if ($n==0) { push @problems, "n=0 but rest nonempty" if length($rest); }
    push @problems, "segment contains '/'" if grep { index($_,'/')>=0 } @segs;
    push @problems, "physical seg lines ($#segs+1) < n=$n" if scalar(@segs) < $n;
  }
  if (@problems) { $bad++; printf "BAD input=%s\n  problems: %s\n  out=%s\n", unpack("H*",$s), join('; ',@problems), unpack("H*",$o); }
}
print "probes=$probes bad=$bad\n";
