#define _GNU_SOURCE
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <sys/wait.h>
#include <stdlib.h>
#include <signal.h>
int main(int argc,char**argv){
  int p[2]; if(pipe(p)) return 2;
  fcntl(p[1],F_SETFL,O_NONBLOCK);          /* writer end non-blocking */
  pid_t c=fork();
  if(c==0){ dup2(p[1],1); close(p[0]); close(p[1]);
            signal(SIGPIPE,SIG_IGN);
            execv(argv[1],&argv[1]); _exit(127); }
  close(p[1]);
  sleep(1);                                 /* let pipe fill up */
  int st; waitpid(c,&st,0);
  /* now drain */
  char buf[4096]; long tot=0,r;
  while((r=read(p[0],buf,sizeof buf))>0) tot+=r;
  fprintf(stderr,"child_exited=%d status=%d signaled=%d sig=%d bytes_delivered=%ld\n",
    WIFEXITED(st),WIFEXITED(st)?WEXITSTATUS(st):-1,WIFSIGNALED(st),WIFSIGNALED(st)?WTERMSIG(st):0,tot);
  return 0;
}
EOF
